WITH expected AS (
  SELECT unnest(ARRAY[
    'ai_execution_logs','app_settings','audit_logs','bonus_ledger','cases',
    'collection_runs','commercial_audit_log','commercial_offers','commercial_orders',
    'commission_ledger','commissions','content_versions','coupons','documenso_envelopes',
    'documenso_recipients','documenso_webhook_events','documents','e2e_test_results',
    'e2e_test_runs','editorial_content','knowledge_chunks','knowledge_document_versions',
    'knowledge_documents','knowledge_embeddings','knowledge_ingestions','knowledge_sources',
    'marketing_automation_queue','marketing_automation_state','marketing_campaigns',
    'marketing_lead_campaigns','marketing_leads','marketing_messages','meta_accounts',
    'meta_tokens','messaging_contacts','messaging_conversations','messaging_messages',
    'notification_subscriptions','notifications','orders','payment_events','payment_orders',
    'payment_webhook_events','payments','platform_events','promotion_campaigns',
    'promotions','publisher_jobs','referral_config','referral_relations','service_pricings',
    'user_profiles'
  ]) AS table_name
),
presence AS (
  SELECT e.table_name,
    EXISTS (SELECT 1 FROM information_schema.tables t WHERE t.table_schema='public' AND t.table_name=e.table_name) AS public_exists,
    EXISTS (SELECT 1 FROM information_schema.tables t WHERE t.table_schema='recovery_backup_20260923' AND t.table_name=e.table_name) AS backup_exists
  FROM expected e
)
SELECT * FROM presence WHERE NOT (public_exists AND backup_exists) ORDER BY table_name;

SELECT 'public_tables' AS item, count(*)::bigint AS value
FROM information_schema.tables WHERE table_schema='public' AND table_type='BASE TABLE'
UNION ALL SELECT 'backup_tables', count(*) FROM information_schema.tables
WHERE table_schema='recovery_backup_20260923' AND table_type='BASE TABLE'
UNION ALL SELECT 'auth_users', count(*) FROM auth.users
UNION ALL SELECT 'backup_auth_users', count(*) FROM recovery_backup_20260923.auth_users
UNION ALL SELECT 'storage_buckets', count(*) FROM storage.buckets
UNION ALL SELECT 'backup_storage_buckets', count(*) FROM recovery_backup_20260923.storage_buckets
UNION ALL SELECT 'storage_objects', count(*) FROM storage.objects
UNION ALL SELECT 'backup_storage_objects', count(*) FROM recovery_backup_20260923.storage_objects
ORDER BY item;

